programs.sol:
"""Approximate a spelling-sensitive response centered on the letter d.

Short d-fragments have different signed responses: dor/dew are positive,
denn/doc/diff negative. The d can also be near the end of the preceding
fragment. Cyrillic text is transliterated for the same spelling test.
Other cues are middle-dot punctuation and a document-opening def token.
Long words and unlisted continuations receive zero, not a semantic guess.
"""
import unicodedata
import regex
from anyascii import anyascii

READS = ()

# Short continuations of a preceding d-bearing fragment.
CONTINUATIONS = {
    'or': 3.7, 'ors': 5.5, 'orm': 6.0, 'oro': 2.2,
    'ew': 5.2, 'oc': -3.0, 'iff': -3.8, 'enn': -5.0,
    'ag': -2.0, 'agger': -1.7, 'og': -2.7,
    'il': 1.9, 'ir': -1.5, 'im': -1.2, 'ib': 2.1,
    'ih': 3.2, 'ior': 3.4, 'icht': 3.0,
    'ql': 1.6, 'yn': -1.3,
}


def plain(text):
    if regex.search(r'\p{Script=Cyrillic}', text):
        text = anyascii(text)
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


def local_fragment(text, s):
    word = s.strip()
    if not word.isalpha() or not word.startswith('d'):
        return 0.0
    tail = word[1:]
    capital = text.strip()[:1].isupper()
    space = text[:1].isspace()
    if tail == 'enn':
        return -3.8 if capital else -6.8
    if tail in ('oc', 'ocs'):
        if capital:
            return -0.7
        if space:
            return -0.6 if tail == 'oc' else 0.0
        return -4.5 if tail == 'oc' else -3.0
    if tail == 'iff':
        return -1.0
    if tail == 'or':
        return 3.0
    if tail.startswith('or') and len(tail) == 3:
        return 1.5
    if tail == 'ew':
        return 4.3
    if tail == 'ow':
        return 3.1
    if tail in ('ag', 'agg'):
        return -1.5
    if tail in ('il', 'ip'):
        return 1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    text = prefix.token_strings[-1]
    s = plain(text)
    value = local_fragment(text, s)
    d = previous.rfind('d')
    if d >= 0 and not s[:1].isspace() and s.isalpha():
        distance = len(previous) - d
        if distance <= 4:
            value += (0.65 ** (distance-1)) * CONTINUATIONS.get(s, 0.0)
    if s and set(s) == {'·'}:
        value = -0.38 * min(len(s), 2)
    if s == 'def' and (start or previous == '<|endoftext|>'):
        value = 4.9
    return (doc, s.strip()), float(value)

"""A sparse collocation response, led by 'sports team' and number types.

Positive values mark sports vocabulary and several compound-noun heads.
Singular 'prime number' is stronger after an indefinite article. Separate
formatting rules approximate document onsets, role markers, a leading
'Title:' label, and repeated middle-dot filler. Most small token-specific
variation is deliberately left unexplained.
"""

READS = ()
SPORTS = {'sport', 'sports', 'football', 'soccer', 'hockey', 'baseball',
          'basketball', 'rugby', 'cricket', 'volleyball', 'racing'}


def phrase_value(word, prior, determiner):
    if word in {'team', 'teams'}:
        if prior == 'sports':
            return 0.87 if word == 'team' else 0.28
        if prior in SPORTS:
            return 0.54 if word == 'team' else 0.24
        return 0.37 if prior == 'on' else 0.16
    if word in {'sports', 'sport'}:
        return 0.25 if prior == 'of' else 0.16
    if word in SPORTS:
        return 0.12
    if word in {'player', 'stadium', 'league', 'leagues'}:
        return 0.36 if prior in SPORTS or prior == 'league' else 0.11
    if word in {'number', 'numbers'}:
        if prior == 'prime':
            if word == 'numbers':
                return 0.35
            if determiner in {'a', 'an'}:
                return 0.74
            return 0.37 if determiner == 'the' else 0.52
        if prior == 'integer':
            return 0.55 if word == 'number' else 0.30
        if prior in {'odd', 'even'}:
            value = 0.50 if prior == 'odd' else 0.41
            if word == 'numbers':
                value *= 0.57
            elif determiner == 'the':
                value *= 0.55
            return value
        if prior in {'real', 'rational', 'binary', 'decimal', 'square'}:
            return 0.18 if word == 'number' else 0.10
        return 0.04
    if word == 'museum':
        return 0.60 if prior in {'art', 'history', 'science', 'and'} else 0.16
    if word == 'party':
        political = {'political', 'democratic', 'republican', 'communist'}
        return 0.27 if prior in political else 0.06
    if word == 'agreement' and prior == 'contractual':
        return 0.59
    if word == 'station' and prior == 'railway':
        return 0.45
    if word in {'post', 'posts'} and prior == 'blog':
        return 0.55
    if word == 'film' and prior == 'documentary':
        return 0.62
    if word == 'game' and prior == 'lottery':
        return 0.57
    if word == 'music':
        return 0.12
    if word == 'care' and prior in {'health', 'nursing', 'home'}:
        return 0.30
    return 0.0


def onset_value(raw):
    text = raw.strip()
    if raw.startswith('<|'):
        return 0.0
    if not text:
        return 0.18
    if text[0].isdigit():
        return 0.12
    if raw.startswith(' '):
        return -0.06
    if text[0].isupper() or (text[0].isalpha() and not text[0].isascii()):
        return -0.29
    if text[0].islower():
        return -0.04
    if text in {')', ']', '}'}:
        return 0.37
    return -0.11


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, before, age = '', '', 0
    else:
        _, previous, before, age = carry
    value = phrase_value(raw.strip().lower(), previous.strip().lower(),
                         before.strip().lower())
    if raw == '<|im_start|>':
        value = -0.055
    elif raw in {'<tool_call>', '</tool_call>',
                 '<tool_response>', '</tool_response>'}:
        value = 0.07
    if age == 0:
        value = onset_value(raw)
    elif age == 1 and previous == 'Title' and raw == ':':
        value = -2.43
    elif raw == '··' and previous == raw:
        value = -1.53
    return (doc, raw, previous, age + 1), float(value)

programs.haiku:
"""Layer-1 MLP neuron 1858 (the down_proj component), read as a phrase detector.

The component is quiet almost everywhere. Its large values come from a few phrase
patterns, all built around the word right after "a" / "an":

- NEGATIVE on a noun for a large social unit, era or setting right after an article:
  "a world", "a society", "a country", "an age", "a time", "a place", "a life".
  "world" and its relatives are the strongest.
- NEGATIVE on "of", "where", "when" right after such a setting noun: "a world of",
  "a time of", "a country where", "a time when".
- POSITIVE on the word that completes a fixed idiom after "a" / "an", optionally with
  one adjective in between: "come to a halt", "put an end", "at a close", "a quick
  look", "on a regular basis", "a half", "a one-off".
- POSITIVE on "of" after a measure or analysis noun: "a total of", "an average of",
  "a summary of", "an analysis of", "a scale of", "a maximum of".
- Weak versions of the "of" rules apply without an article ("the country of"), and
  "other" after "any" / "or" is mildly positive.

Everything else predicts 0. It captures the largest and most regular values of the
component; the many small values elsewhere are not modelled.
"""

READS = ()

ARTICLES = {"a", "an", "un", "une"}
# strongest negatives: large social units and eras
WORLDS = {"world", "mundo", "monde", "society", "culture", "land", "country", "nation", "age", "era"}
# weaker negatives: other nouns for places, periods, groups and stories
SETTING = WORLDS | {
    "time", "place", "life", "city", "town", "village", "community", "government",
    "environment", "generation", "population", "species", "year", "family", "company",
    "organization", "industry", "economy", "team", "game", "competition", "battle", "war",
    "history", "future", "period", "week", "day", "moment", "story", "tale",
}
# strongest positives: the word that ends "come to a halt", "a quick ...", "on a regular basis"
IDIOM_STRONG = {"quick", "end", "close", "halt", "stop", "boil"}
# weaker positives: other idiom ends and quantity words
IDIOM = IDIOM_STRONG | {
    "one", "two", "half", "look", "friend", "trip", "scale", "early", "recent",
    "previous", "separate", "limited", "try", "check", "level", "nature", "side",
}
# nouns for a measure, amount or analysis: "of" after them is positive
MEASURE_NOUNS = {
    "total", "average", "maximum", "minimum", "factor", "summary", "scale", "review",
    "search", "analysis", "study", "increase", "reduction", "improvement", "understanding",
    "examination", "description", "example", "measure", "ratio", "percentage", "fraction",
    "score", "copy", "lack", "loss",
}
BIG_MEASURES = {"total", "average", "summary", "review", "analysis", "maximum", "minimum", "scale", "factor"}
LINKERS = {"where", "when", "that", "who"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    t = prefix.position
    docs = prefix.document_ids
    strs = prefix.token_strings

    def back(k):
        # the word k positions back, or "" across a document boundary
        if t - k < 0 or docs[t - k] != docs[t]:
            return ""
        return _word(strs[t - k])

    w, p, pp = back(0), back(1), back(2)
    value = 0.0
    if w == "of":
        if pp in ARTICLES:  # "a X of"
            if p in MEASURE_NOUNS:
                value = 1.5 if p in BIG_MEASURES else 0.8
            elif p in WORLDS:
                value = -2.0
            elif p in SETTING:
                value = -0.8
        elif p in SETTING:  # "the X of", without an article
            value = -0.4
        elif p in MEASURE_NOUNS:
            value = 0.4
    elif p in SETTING and w in LINKERS:  # "a country where", "a time when"
        value = -0.7 if p in WORLDS else -0.4
    elif w == "other" and p in {"any", "or"}:  # "any other", "or other"
        value = 0.8
    elif w == "basis" and p != "the":  # "on a regular basis"
        value = 1.3
    elif p in ARTICLES:  # the word right after "a" / "an"
        if w in WORLDS:
            value = -2.5
        elif w in SETTING:
            value = -1.0
        elif w in IDIOM_STRONG:
            value = 2.5
        elif w in IDIOM:
            value = 1.0
    elif pp in ARTICLES and p.isalpha():  # one adjective between article and noun
        if w in SETTING:
            value = -0.6
        elif w in IDIOM:
            value = 0.7
    return carry, value

programs.sol:
"""Approximate a byte-boundary and diacritic-sensitive component.

The largest positive responses are Arabic short vowels and Hebrew pointing.
Shadda is especially strong on an assimilated Arabic definite article. Negative
responses occur inside split UTF-8 characters. For incomplete Han characters,
use their possible radicals, stroke counts and simplified/traditional forms;
for emoji use the possible Unicode names' categories. These are coarse proxies
for byte-range sensitivity, not recognition of an unseen completed character.
Ordinary text is near zero. State keeps an unfinished character, one preceding
token and a short text suffix, and resets at document boundaries.
A Thai tone-mark sequence also gets a positive response. Small extra rules
cover initial tabs and repeated middle-dot tokens.
"""
import unicodedata as ud
from collections import Counter
from functools import lru_cache
import unihan
import wordnet
import regex
from opencc import OpenCC

TO_TRADITIONAL = OpenCC('s2t')

READS = ()

# Arabic vowel signs: a, u, i, followed by their doubled (tanwin) forms.
ARABIC_VOWELS = {
    'َ': 1.4,
    'ُ': 2.25,
    'ِ': 4.3,
    'ً': 0.27,
    'ٌ': 2.6,
    'ٍ': 2.0,
}
SUN_LETTERS = set('تثدذرزسشصضطظلن')


# The Unicode ordering groups many Han characters by their written radical.
# These are coarse family averages, not a guess at the unknown final byte.
RADICAL_RESPONSES = {
    'fish': -4.5,
    'wine': -2.4,
    'gold': -3.0,
    'silk': -0.95,
}


@lru_cache(maxsize=1024)
def partial_family(fragment):
    if len(fragment) == 2 and 0xe4 <= fragment[0] <= 0xe9:
        base = ((fragment[0] & 15) << 12) | ((fragment[1] & 63) << 6)
        radicals = Counter(unihan.radical(chr(base + i)) for i in range(64))
        radical = radicals.most_common(1)[0][0]
        name = unihan.radical_name(radical) if radical else ''
        value = RADICAL_RESPONSES.get(name, -0.08)
        candidates = [chr(base + i) for i in range(64)]
        if name in {'dog', 'bird'}:
            strokes = sum(unihan.strokes(ch) or 0 for ch in candidates) / 64
            if name == 'dog':
                value = -min(8.2, max(0.4, 1.3 * (strokes - 9)))
            else:
                value = -min(8.0, max(0.4, strokes - 12))
        simplified = sum(TO_TRADITIONAL.convert(ch) != ch for ch in candidates)
        return value * 0.1 if simplified > 32 else value
    if len(fragment) == 3 and fragment[0] == 0xf0:
        base = ((fragment[1] & 63) << 12) | ((fragment[2] & 63) << 6)
        names = [ud.name(chr(base + i), '').lower() for i in range(64)]
        if any('regional indicator' in name for name in names):
            return -3.1
        if not regex.fullmatch(
                r'\p{Block=Miscellaneous_Symbols_and_Pictographs}', chr(base)):
            return -0.1
        animals = foods = 0
        for name in names:
            noun = name.split(' face')[0]
            animals += bool(wordnet.is_a(noun, 'animal'))
            foods += bool(wordnet.is_a(noun, 'food') or
                          wordnet.is_a(noun, 'plant'))
        if animals > 24:
            return -6.0
        if foods > 24:
            return -4.0
        return -0.1
    return -0.15


def predict(carry, raw, document):
    first = carry is None or carry[0] != document
    if first:
        pending, previous, tail = b'', '', ''
    else:
        _, pending, previous, tail = carry
    before = pending
    joined = pending + raw
    try:
        text = joined.decode('utf-8')
        pending = b''
    except UnicodeDecodeError as error:
        pending = (joined[error.start:]
                   if error.reason == 'unexpected end of data' else b'')
        text = joined.decode('utf-8', 'replace')
    value = -0.07 if first else 0.0
    continuation = len(raw) == 1 and 0x80 <= raw[0] < 0xc0
    if continuation and before:
        lead = before[0]
        if len(before) == 1 and len(pending) == 2:
            if 0xe4 <= lead <= 0xe9:
                value = partial_family(pending)
            elif 0xea <= lead <= 0xed:
                value = -0.2
            else:
                value = -0.1
        elif len(before) == 2 and len(pending) == 3:
            value = partial_family(pending)
        elif not pending:
            value = 0.03

    if text in ARABIC_VOWELS:
        value = ARABIC_VOWELS[text]
    elif text == 'ّ':
        stem = previous.strip()
        # The article and its following sun letter may span several tokens.
        if (len(tail) >= 3 and tail[-3:-1] == 'ال'
                and tail[-1] in SUN_LETTERS):
            value = 6.3
        elif previous == 'ِ':
            value = 4.5
        elif stem.endswith('ي'):
            value = 0.1
        else:
            value = 0.8 if len(stem) == 1 else 0.4
    elif len(text) == 1:
        name = ud.name(text, '')
        if name.startswith('HEBREW POINT'):
            value = 0.5 if text == 'ָ' else 2.7
        elif text == '้':
            value = 0.65 if previous.endswith('ั') else 0.08

    token = raw.decode('utf-8', 'replace')
    if first and token == '\t':
        value = 2.16
    # A run made entirely of middle dots behaves like its isolated first token.
    if token == '··' and (first or previous == token):
        value = -1.956
    tail = (tail + text.replace('�', ''))[-16:]
    return (document, pending, token, tail), float(value)


def step(carry, prefix, upstream):
    return predict(carry, prefix.token_bytes[-1], prefix.document_ids[-1])

"""A sparse text-pattern approximation, not a general semantic detector.

Recognize initial title labels and source-format delimiters, middle-dot
leaders, the Mandarin 'rao' phonetic family, and Arabic/Hebrew vowel
pointing. These are recognizable large-response patterns in training;
irregular lexical responses are deliberately omitted. Other text is close
to zero. Initial-token rules persist through an initial repeated-token run.
State and UTF-8 decoding reset between documents.
"""
import codecs
from functools import lru_cache
import unicodedata
import regex
from pypinyin import lazy_pinyin
from opencc import OpenCC

READS = ()
_SIMPLIFY = OpenCC('t2s')


@lru_cache(maxsize=4096)
def rao_value(text):
    if regex.fullmatch(r'\p{Script=Han}', text):
        if lazy_pinyin(text) == ['rao']:
            return -5.3 if _SIMPLIFY.convert(text) != text else -3.3
    return 0.0


def initial_value(text):
    if text == '<|endoftext|>':
        return 2.35
    if text == '\x00':
        return 4.73
    if text == '<|im_start|>':
        return 0.22
    if text == 'Title':
        return 0.78
    if text.startswith('#'):
        return 0.82
    if text.startswith('/*'):
        return 0.75
    if text.startswith(('"""', "'''")):
        return 1.1
    if text == r'\t':
        return 2.77
    if text == r'\n':
        return 1.88
    if text.isspace():
        return 0.7 if text.count('\n') > 1 else 0.2
    return 0.12


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf8')('replace')
        head, recent, first, initial_run = '', [], token, True
    else:
        _, decoder, head, recent, first, initial_run = carry
        initial_run = initial_run and token == first
    text = decoder.decode(prefix.token_bytes[-1])
    head = (head + text) if head is not None else None
    value = initial_value(token) if initial_run else 0.0
    if head == 'Title:':
        value = 6.68
    elif head == '---\ntitle:':
        value = 0.87
    if head is not None and len(head) > 16:
        head = None
    if len(text) >= 2 and set(text) == {'·'}:
        value = 0.99
    rao = rao_value(text.strip())
    if rao:
        value = rao
    names = [unicodedata.name(ch, '') for ch in text]
    arabic = any(name.startswith('ARABIC') for name in names)
    hebrew = any(name.startswith('HEBREW') for name in names)
    amark = sum(name.startswith('ARABIC') and unicodedata.category(ch) == 'Mn'
                for name, ch in zip(names, text))
    hmark = sum(name.startswith('HEBREW') and unicodedata.category(ch) == 'Mn'
                for name, ch in zip(names, text))
    if arabic:
        # Kasra is /i/, damma /u/, fatha /a/. The first two are stronger.
        vowels = {'ِ': 3.03, 'ُ': 0.95, 'َ': -0.11,
                  'ْ': 0.23, 'ٍ': 1.1}
        value = -0.036 + 0.15 * amark + vowels.get(text, 0.0)
        value += 0.1 * sum(pair[0] for pair in recent)
    if hebrew:
        value = 0.43
        if hmark:
            name = ' '.join(names)
            if any(vowel in name for vowel in ('HIRIQ', 'TSERE', 'SEGOL')):
                value = 2.8  # front vowel points
            elif 'METEG' in name:
                value = 5.0  # metrical/stress mark
            elif 'HOLAM' in name or 'DAGESH' in name:
                value = 1.8
            else:
                value = 0.15
        else:
            value += 0.1 * sum(pair[1] for pair in recent)
    recent = (recent + [(amark, hmark)])[-8:]
    return (doc, decoder, head, recent, first, initial_run), value

"""Approximate a mostly negative response to short 'se' word fragments.

Accents and alphabetic scripts are romanized (Han readings are not used).
The response is strongest for short fragments and for continuations of 's'
or 'se' across a token boundary. Common whole words are usually weaker;
ordinary inflections and long fragments have their own, smaller estimates.
Setter-method names have a small positive response. Two secondary rules
handle document-initial bare 'se' and runs of repeated middle dots.
These rules approximate the dominant spelling pattern, not every activation.
"""
import re
from functools import lru_cache

import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()

# These are spelling variants of s, not endings of arbitrary transliterations.
S_LETTERS = frozenset('sSſšŠşŞșȘсСσΣς')
INFLECTIONS = frozenset(('ed', 'es', 'er', 'ers', 'est', 'en', 'ent', 'ern', 'e'))
CONSONANTS = frozenset('bcdfghjklmnpqrstvwxyz')


@lru_cache(maxsize=30000)
def spelling(text):
    if regex.search(r'\p{Script=Han}', text):
        return ''
    return anyascii(text.replace('ä', 'e').replace('Ä', 'E')).lower()


@lru_cache(maxsize=50000)
def frequency(word):
    return zipf_frequency(word, 'en') if word and len(word) < 40 else 0.0


def response(text, current, previous, old_word, word, old_raw, initial):
    fragment = current.lstrip(' \t\n\r./-_(')
    letters = re.match('[a-z]+', fragment)
    fragment = letters.group() if letters else ''
    n = len(fragment)
    joined = frequency(word)
    previous = previous.rstrip('.')
    continuing = bool(current and previous and previous[-1].isalpha()
                      and (current[0].isalpha() or current[0] == '.'))

    if text and set(text) <= {'·'}:
        return -0.94 if len(text) >= 2 and old_raw == text else 0.0
    if re.match(r'[ .(_]*set[A-Z][a-z]', text):
        return 0.6
    if text.strip().lower() == 'setter':
        return 0.4

    if fragment.startswith('se'):
        if initial and text == 'se':
            return 5.07
        if n <= 4 and joined >= 4.5:
            return -0.11
        if n == 2:
            return -0.78
        if n == 3:
            return -0.69
        return -0.24 if n == 4 else -0.07

    if continuing and previous.endswith('se'):
        if joined >= 4.5 or frequency(old_word) >= 5.0:
            return -0.13
        if fragment and fragment[0] in CONSONANTS:
            return -1.92 if n <= 3 else -0.4
        return -0.3

    if continuing and old_raw and old_raw[-1] in S_LETTERS:
        if fragment.startswith('e'):
            if joined >= 4.5:
                return -1.24
            if len(previous) > 5:
                return -0.22
            cyrillic = bool(regex.search(r'\p{Script=Cyrillic}', text))
            if text.strip().lower() in INFLECTIONS and not cyrillic:
                return -0.66
            if n <= 3:
                return -1.27
            return -1.95 if cyrillic else -0.28

    return -0.02 if 'se' in fragment and n <= 4 else 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    initial = carry is None or carry[0] != doc
    if initial:
        previous = old_word = old_raw = ''
    else:
        _, previous, old_word, old_raw = carry
    current = spelling(text)
    full = old_word + current if current[:1].isalpha() else current
    tail = re.search('[a-z]+$', full)
    word = tail.group()[-40:] if tail else ''
    value = response(text, current, previous, old_word, word, old_raw, initial)
    return (doc, current, word, text), value

programs.haiku:
"""Candidate v4: the 'se' syllable (Latin s+e, or Cyrillic с+е) as a word piece."""
READS = ()
SE_LATIN = {"se", "sec", "sed", "seg", "sem", "sew", "sea", "see", "seed", "set", "ser", "sel", "sex", "sep", "sey", "sen", "sic"}
SE_CYRILLIC = {"ед", "ев", "сет", "сед", "сек", "сем"}
VALUE = -0.5
def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip().lower()
    return None, (VALUE if tok in SE_LATIN or tok in SE_CYRILLIC else 0.0)

programs.sol:
"""Mostly a detector for the start of another quoted mapping key.

A quote after a completed string-valued entry gives a large positive
response, especially after short values. Opening a quoted object and
indented keys give smaller responses. Other rules cover diff hunk
coordinates, shell here-documents, Java static imports, the Russian
existence verb, and the blank line ending a reasoning block.

Only the last 512 characters are retained, reset at document boundaries.
Everything else predicts zero; this leaves much small lexical variation
unexplained.
"""
import re

READS = ()

# Match the value just finished, not a quote in ordinary prose.
CLOSED_VALUE = re.compile(
    r'''"\s*(?::|=>)\s*"([^"\n]*)"\s*,\s*$'''
    r'''|'\s*(?::|=>)\s*'([^'\n]*)'\s*,\s*$'''
)
POSSESSOR = re.compile(r'у (?:меня|тебя|него|неё|нас|вас|них)$')


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    bare = token.replace('\\', '')
    context = before.replace('\\', '')
    value = 0.0

    if bare.strip() in ('"', "'"):
        quote = bare.strip()
        previous_value = CLOSED_VALUE.search(context)
        if previous_value:
            text = next(x for x in previous_value.groups() if x is not None)
            if '\n' in previous_value.group(0):
                value = 0.75
            elif quote == '"':
                value = max(0.5, 1.95 - 0.005 * len(text))
            else:
                value = 0.95
        elif before.rstrip().endswith(('{', '[')):
            value = 0.65
        elif re.search(r'(?:\n|\\n)[ \t]+$', before):
            if quote == "'":
                value = 0.9
            elif before.rstrip().endswith(','):
                value = 0.65
        elif re.search(r'''["']\s*\}\s*,\s*$''', context):
            value = 0.9
    elif bare in (' {"', " {'"):
        value = 0.75
    elif token.strip() == 'EOF' and re.search(r'''<<\s*["']?$''', before):
        value = 1.7
    elif token == ' -' and before.endswith('@@'):
        value = 1.45
    elif token == ' static' and re.search(r'\bimport$', before):
        value = 1.85
    elif token == ' есть':
        value = -1.8 if POSSESSOR.search(before) else -0.5
    elif token == '\n\n' and before.endswith('</think>'):
        value = -0.18

    return (document, (before + token)[-512:]), value

"""Spelling-sensitive 'shallow' signal, not a general estimate of depth.

Recognize shallow, its Han spellings, and a few related surface/thin words.
There are also smaller lookalike-word responses and negative responses to
ala/alo/aro-like syllables at subword boundaries. State is only a short text
suffix, reset at document boundaries; no token IDs are used.
The negative branch is an observed subword counter-response, not an
antonym rule. Smaller unrecognized token/context effects are left at zero.
"""
import re
from anyascii import anyascii

READS = ()


def response(previous, token, first):
    text = previous + token
    low = text.lower()
    # A match must be completed now, not merely occur in earlier text.
    for match in re.finditer(r'\bshallow', low):
        if match.end() > len(previous):
            return 'shallow', 9.6
    if '浅' in token or '淺' in token:
        return 'han_shallow', 8.8
    if '薄' in token:
        if previous.endswith(('浅', '淺')):
            return 'shallow_thin', 7.0
        return 'thin', 0.55
    if token == '淡':
        return 'light', 2.3
    if '浮' in token:
        return 'floating', 1.8
    if '談' in token:
        return 'traditional_talk', 1.6
    word = token.strip().lower()
    if word == 'superficial':
        return 'superficial', 1.15
    if word == 'shall':
        return 'shall', 0.3
    if not token[:1].isspace():
        if re.search(r'\bshoal$', low):
            return 'shoal', 6.0
        if re.search(r'\bashore$', low):
            return 'ashore', 3.1
        if re.search(r'shore[ds]?$', low):
            return 'shore_fragment', 1.2
        if previous.lower().endswith('dis') and word.startswith('allow'):
            return 'disallow', 3.8 if word == 'allow' else 2.5
        # Transliteration extends the same spelling rule to Cyrillic and kana.
        syllable = anyascii(token)
        before = anyascii(previous[-8:]).lower()
        if re.fullmatch(r'al[ao]|aro', syllable):
            if before.endswith(('k', 'sh')):
                return 'liquid_after_k_sh', -0.5
            return 'liquid_syllable', -2.0 if token.isascii() else -0.25
        if re.fullmatch(r'a[lr]{1,2}[aou][lnrs]?', syllable):
            return 'long_liquid_syllable', -0.4
        if re.fullmatch(r'o[as]?', syllable):
            if before.endswith(('al', 'ar')):
                return 'a_liquid_o', -2.0
            if re.search(r'[eio][lr]$', before):
                return 'other_liquid_o', -0.2
        if syllable.startswith('a') and before.endswith(('al', 'ar')):
            return 'a_liquid_a', -0.2
        if syllable == 'ro' and before.endswith('a'):
            return 'a_ro', -1.5
    if word in ('offshore', 'onshore'):
        return 'coast', 0.6
    if first:
        if word == 'an':
            return 'initial_an', 1.8
        if word == 'a':
            return 'initial_a', 0.8
        return 'initial', 0.17
    return 'other', 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = b'' if first else carry[1]
    newest = prefix.token_bytes[-1]
    # Decode jointly so that a character split across tokens is completed here.
    text = (previous + newest).decode('utf-8', errors='ignore')
    old = previous.decode('utf-8', errors='ignore')
    token = text[len(old):]
    _, value = response(old, token, first)
    return (doc, (previous + newest)[-80:]), value

programs.haiku:
"""Layer-1 MLP feature that reads the word "shallow" (and its Chinese synonyms).

Its activation is large and positive on "shallow" itself, on the Chinese words for shallow
(浅, 淺), and on "allow" when it finishes a word split as "sh" + "allow" (SHALLOW -> SH|ALLOW).
Weaker positives go to other thin/light/superficial words (薄 thin, 淡 light, 浮 superficial)
and to "shall". It is negative on a few name fragments inside longer words, such as "ala"
in Sinhala or Petaluma, "uma" in Petaluma, "ando" in Zalando. At the first token of a
document it gives a small positive bias, since the activation there is shifted up on
average. Everything else is 0.
"""
READS = ()

SHALLOW = {" shallow", "shallow", "浅", "淺"}
THIN_LIGHT = {"薄", "淡", "浮"}
SHALL = {" shall", "shall"}
NAME_FRAGMENTS = {"ala": -2.0, "alo": -2.4, "aro": -1.9, "uma": -0.6, "ando": -0.5}
DOC_START = 0.2


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().lower() if prefix.position > 0 else ""
    first = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    value = DOC_START if first else 0.0
    if tok in SHALLOW or (tok in {"ALLOW", "allow"} and prev == "sh"):
        value = 9.0
    elif tok in THIN_LIGHT:
        value = 1.7
    elif tok in SHALL:
        value = 0.4
    elif tok in NAME_FRAGMENTS:
        value = NAME_FRAGMENTS[tok]
    return None, value

programs.sol:
"""Predict a script/encoding signal and document/message boundaries.

Ordinary tokens from the listed non-Latin scripts get a positive script
average; other ordinary tokens get zero. Incomplete UTF-8 pieces also get a
positive value, smaller after a space. At document starts (including a run
of repeated initial tokens), script, case, numbers, whitespace, articles,
and code-declaration words instead determine the prediction. Protocol tags
have their own signed values, with early-document adjustments that decay
with position. This deliberately omits ordinary word-specific variation.
"""
from functools import lru_cache
import regex
import math

READS = ()

SCRIPTS = [
    ('Han', 0.78),
    ('Cyrillic', 0.90),
    ('Arabic', 1.40),
    ('Hiragana', 0.46),
    ('Katakana', 1.47),
    ('Hangul', 0.92),
    ('Devanagari', 1.12),
    ('Thai', 1.20),
    ('Hebrew', 1.80),
    ('Greek', 0.73),
]
PATTERNS = [(regex.compile(r'\p{Script=' + name + '}'), name, level)
            for name, level in SCRIPTS]

@lru_cache(maxsize=24000)
def ordinary(raw):
    text = raw.decode('utf-8', 'replace').strip()
    if '\ufffd' in text:
        return 1.3 - 0.7 * raw.startswith(b' '), 'fragment'
    for pattern, name, level in PATTERNS:
        if pattern.search(text):
            return level, name
    return 0.0, 'latin'


def step(carry, prefix, upstream):
    raw = prefix.token_bytes[-1]
    text = raw.decode('utf-8', 'replace')
    word = text.strip()
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    position = 0 if first else carry[2] + 1
    initial_raw = raw if first else carry[3]
    initial_run = first or (carry[4] and raw == initial_raw)
    value, script = ordinary(raw)

    if initial_run:
        if script == 'Cyrillic':
            value = 4.0 if word.istitle() else 5.5
        elif script == 'Arabic':
            value = 1.6
        elif script in ('Han', 'fragment'):
            value = -1.0
        elif script == 'Katakana':
            value = 2.4
        elif script == 'Hiragana':
            value = 0.7
        elif script == 'Hangul':
            value = 1.2
        elif script == 'Greek':
            value = -0.3
        elif not word:
            value = -1.6
        elif word.isdigit():
            value = -4.2
        elif word.isupper() and len(word) > 1:
            value = 0.5
        elif word.isalpha():
            if word.istitle():
                value = -0.4 if text.startswith(' ') else -3.2
            else:
                value = -1.8
            if word == 'The' and not text.startswith(' '):
                value = -7.7
            elif word == 'the':
                value = -5.4
            elif word in ('class', 'package') and not text.startswith(' '):
                value = -8.3  # source-code declarations
            elif word in ('import', 'from') and not text.startswith(' '):
                value = -12.8  # import statements
        else:
            value = -2.8

    if word == '<|im_end|>':
        if previous == '</tool_call>':
            value = -13.3 + 8.5 * math.exp(-position / 13)
        elif previous == '</tool_response>':
            value = -12.6 + 4.0 * math.exp(-position / 13)
        else:
            value = -14.3 + 6.0 * math.exp(-position / 10)
    elif word == '<|im_start|>':
        value = -0.4 + 1.71 * math.exp(-position / 20)
    elif word == '<|endoftext|>':
        value = -6.46 if initial_run else -0.02
    elif word == '</tool_response>':
        value = 3.85
    elif word == '</tool_call>':
        value = -4.7 + 5.2 * math.exp(-position / 10)
    elif word == '<think>':
        value = 1.0 + 1.9 * math.exp(-position / 15)
    elif word == '</think>':
        value = -1.5 + 2.3 * math.exp(-position / 20)
    elif word == '<tool_call>':
        value = 0.37
    elif word == '<tool_response>':
        value = -0.06
    elif word == 'assistant' and previous == '<|im_start|>':
        value = 0.55
    return (doc, word, position, initial_raw, initial_run), float(value)

programs.haiku:
"""Coordinating and quantifying words.

The component reads the word just written, and sometimes the word before it. Its
activation is a signed size, roughly:
- "and" pushes positive when it joins singular things: strongest after a number, bracket
  or capitalised name, weaker after a comma, and near zero after a plural noun ("tools and");
- "or" pushes negative;
- "a" / "an" push negative: strongly right after "or" ("X or a Y"), moderately after a
  preposition ("of a", "from a", "in an");
- quantifiers "all", "both", "same", "two" push positive; "one", "some" push negative.
Every other word gives 0.
"""

READS = ()

PREPOSITIONS = {"of", "from", "about", "during", "in", "into", "for", "by", "through", "within",
                "over", "at", "on", "to", "with", "as", "than", "like", "such"}
POSITIVE_QUANTIFIERS = {"all", "both", "same", "two"}
NEGATIVE_QUANTIFIERS = {"one", "some"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    before = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    if word == "and":
        if before == ",":
            return None, 0.08
        if before[-1:].isdigit() or before[-1:] in (")", "]", "$"):
            return None, 0.33
        if before[:1].isupper():
            return None, 0.35
        if before.endswith("s") and len(before) > 3:
            return None, 0.0
        return None, 0.28
    if word == "or":
        return None, -0.3
    if word in ("a", "an"):
        if before in ("or", "nor"):
            return None, -1.7
        if before in PREPOSITIONS:
            return None, -0.5
        return None, -0.05
    if word in POSITIVE_QUANTIFIERS:
        return None, 0.13
    if word in NEGATIVE_QUANTIFIERS:
        return None, -0.14
    return None, 0.0

programs.sol:
"""A local spelling/phonetic approximation, not a general dance-topic detector.

Positive responses mark Indic dental consonants and the marks or r following
one, plus Thai ท and its vowel marks. Negative responses recognize bare
'dance', 'dart', and selected d/t-wordpiece joins.
There is also a small opening-position offset. Incremental UTF-8 decoding
handles byte-fragment tokens. The spelling rules are intentionally narrow:
merged 'accordance', for example, is not treated as bare 'dance'.
"""
import codecs
import re
import unicodedata as ud

READS = ()
DENTALS = set('तथदधਤਥਦਧதతథదధতথদধತಥದಧതഥദധ')
RHOTICS = set('रਰரరরರര')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    prev, tail, pending = ('', '', b'') if first else carry[1:]
    first |= prev == '<|endoftext|>'
    if first:
        prev, tail, pending = '', '', b''
    text = prefix.token_strings[-1]
    raw = pending + prefix.token_bytes[-1]
    chars, used = codecs.utf_8_decode(raw, 'replace', False)
    pending = raw[used:]
    s, p = text.lower(), prev.lower()
    value = 0.0
    if first:
        value = -0.11 - 0.11 * any(c.isalpha() for c in text)
        if text.startswith(' '):
            value += 0.07

    oldbase = next((c for c in reversed(tail)
                    if not ud.category(c).startswith('M')), '')
    if any(c in DENTALS for c in chars):
        value += 0.9 + 0.75 * any(c in 'ਤਦ' for c in chars)
    if oldbase in DENTALS:
        if chars and ud.category(chars[0]).startswith('M'):
            value += 1.6
        # Many vowel/nasal marks are in the next 64-codepoint region after
        # the consonants. Recognize that region's unfinished UTF-8 prefix.
        mark_region = chr((ord(oldbase) // 64 + 1) * 64).encode('utf-8')
        if not chars and pending == mark_region[:2]:
            value += 1.6
        if chars and chars[0] in RHOTICS:
            value += 3.4

    if chars == 'ท':
        value += 0.4
    if oldbase == 'ท' and chars and ud.category(chars[0]).startswith('M'):
        value += 0.6
    if text == ' dart':
        value -= 0.45

    if s.strip() in {'dance', 'dances'}:
        value -= 1.0 if s.strip() == 'dance' else 0.4
        if text.strip()[:1].isupper():
            value -= 0.5
        if s.strip() == 'dance' and p.strip() in {
            'to', 'can', 'could', 'will', 'would'
        }:
            value += 0.7
    if p.endswith(('t', 'd')) and re.fullmatch(
        r'anc(?:e|ing)?|angle|eta|ind', s
    ):
        value -= 1.0
    if p.endswith('d') and s.startswith('anc'):
        value -= 0.4
    if s == 'dat' and p.endswith(('up', 'opp')):
        value -= 1.2

    return (doc, text, (tail + chars)[-6:], pending), value

"""Respond mainly to lower-case 'for' and forms meaning 'for' in other languages.

Indentation and punctuation suppress the English response; a preceding
title-case word raises it slightly. Recent word frequencies distinguish Italian
'per' from rates and word fragments, Spanish from Portuguese 'para', and
Bulgarian from Russian 'за'. Arabic word-initial lam is another cue. Separate
rules model digits 4 and 5, especially when they follow letters.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

# Prepositions of purpose, destination, or benefit, in several languages.
FOR_WORDS = {
    'für': 1.15, 'för': 1.15, 'для': 1.28, 'dla': 1.2,
    'pentru': 1.35, 'voor': 0.45, 'untuk': 0.85, 'pra': 0.7,
}

@lru_cache(maxsize=8192)
def frequency(word, language):
    return zipf_frequency(word, language)


def language_margin(text, language, alternative='en'):
    words = re.findall(r"[^\W\d_]+", text.lower())[-20:]
    return sum(frequency(w, language) - frequency(w, alternative) for w in words)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, previous, text = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    last = previous[-1:]
    value = 0.0
    if word == 'for':
        match = re.search(r"[^\W\d_]+$", text)
        preceding_word = match[0] if match else ''
        value = 0.96
        value += 0.21 * preceding_word.istitle()
        if not token.startswith(' '):
            value -= 0.2
        if token.startswith('\t'):
            value -= 0.26
        if last.isspace():
            value -= 0.94
        elif last and not last.isalnum():
            value -= 0.28
        if not previous:
            value = 0.15
    elif word == 'FOR':
        value = 1.0
    elif word == 'For':
        value = 0.05
    elif token in {'.for', '-for'}:
        value = 0.2 if token.startswith('.') else 0.65
    elif token.startswith(' ') and word.lower() in FOR_WORDS:
        value = FOR_WORDS[word.lower()]
    elif word.lower() == 'para':
        value = 1.55 if language_margin(text, 'es', 'pt') > 1 else 0.6
    elif word.lower() == 'per':
        boundary = token.startswith(' ') or not last.isalpha()
        competitors = ('en', 'fr', 'es', 'pt', 'de', 'id', 'ro')
        italian = boundary and all(
            language_margin(text, 'it', lang) > 1 for lang in competitors
        )
        value = 2.65 if italian else -0.05
    elif word.lower() == 'pour':
        if language_margin(text, 'fr') > 1:
            value = 2.6 if word == 'pour' else 1.8
    elif word.lower() == 'за':
        value = 1.8 if language_margin(text, 'bg', 'ru') > 1 else 0.0
    elif token.startswith(' ل'):
        value = 1.3
        if token.startswith(' للأ'):
            value = 1.8
        elif word in {'لا', 'لها', 'لك', 'لي'}:
            value = 0.85
    elif word in {'4', '5'} and previous:
        identifier = last.isalpha() or last == '_'
        if word == '4':
            value = 0.9 if identifier else -0.13 if last.isdigit() else 0.04
            if last.isspace():
                value = 0.0 if '\n' in previous else 0.1
        else:
            value = 0.5 if identifier else 0.1 if last.isdigit() else 0.0
            if last.isspace():
                value = 0.14
    return (doc, token, (text + token)[-250:]), value

"""A numeral response, rather than a general detector of numbers in prose.

Most text is near zero. Digits 2--9 have a negative response; zero and one
are weaker. Number continuations, decimal halves and list beginnings alter
that response. Spelled-out and Chinese small numbers respond more weakly.
First document positions are calibrated separately. These rules keep the
large numeral response, not idiosyncratic responses to arbitrary words.
"""
import unicodedata
import regex
import inflect

READS = ()
# Entries are numeral values zero through nine, not vocabulary IDs.
DIGIT = (0.10, 0.07, -0.74, -0.76, -0.67,
         -0.97, -0.56, -0.60, -0.46, -0.32)
FIRST = (0.97, -0.30, 0.83, 1.35, 1.36,
         1.98, 1.64, 1.95, 1.55, 1.45)
_inflection = inflect.engine()
WORD_VALUES = {_inflection.number_to_words(n): n for n in range(10)}


def written_number(text):
    """Small number words and non-ASCII numeral glyphs."""
    word = text.strip().lower()
    if word in WORD_VALUES:
        n = WORD_VALUES[word]
        if n < 2:
            return 0.11
        if n == 5:
            return -0.40
        return -0.12 if n < 5 else 0.0
    ordinal = word.startswith('第')
    glyph = word[1:] if ordinal else word
    if len(glyph) != 1:
        return -0.01
    if regex.fullmatch(r'\p{Script=Han}', glyph):
        n = unicodedata.numeric(glyph, -1)
        if not 0 <= n <= 10:
            return -0.01
        value = (0.36 if n < 2 else -0.74 if n == 5 else
                 -0.38 if n < 5 else -0.30 if n == 6 else
                 0.50 if n == 10 else -0.04)
        if ordinal:
            value = 0.04 if n == 1 else value - 0.25
        return value
    n = unicodedata.digit(glyph, -1)
    if 0 <= n <= 9:
        if 'FULLWIDTH' in unicodedata.name(glyph, '') and n < 2:
            return -0.28
        return DIGIT[n] - (0.2 if 'SUBSCRIPT' in unicodedata.name(glyph, '')
                          and n >= 2 else 0.0)
    return -0.01


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, count, line_start = ('', 0, True)
    if carry is not None and carry[0] == doc:
        previous, count, line_start = carry[1:]
    text = prefix.token_strings[-1]
    digit = int(text) if len(text) == 1 and text in '0123456789' else -1
    value = written_number(text) if digit < 0 else DIGIT[digit]
    if count == 0:
        value = FIRST[digit] if digit >= 0 else 0.45
    elif digit >= 0:
        if len(previous) == 1 and previous in '0123456789':
            prior_digit = int(previous)
            if digit == 0:
                value = -0.35 if prior_digit == 0 else 0.0
            elif digit == 1:
                value = -0.49
            else:
                # Continuations are stronger, especially after even digits.
                if digit == 5:
                    value += 0.05
                else:
                    value -= 0.35 if digit in (2, 6) else 0.25
                if prior_digit == 1:
                    value += 0.38
                elif prior_digit % 2 == 0:
                    value -= 0.18
        elif previous == '.' and digit == 5:
            value += 0.88
        elif line_start and digit == 1:
            value -= 0.50
        if count == 1 and digit >= 2:
            value -= 0.41
    if '\n' in text:
        line_start = not text.rsplit('\n', 1)[1].strip()
    elif text.strip():
        line_start = False
    return (doc, text, count + 1, line_start), value

"""Recognize m-ending token fragments, rather than the meaning of their words.

Cyrillic -ом/-ем endings are positive, especially -ном, -ком and
sibilant + ем. Latin consonant abbreviations ending in M are negative,
most strongly when continuing an uppercase, vowel-free word. Ordinary
complete words ending in m have little response. Token boundaries matter.
Small positive responses also cover short -em/-om/-ym, accented -ém/-ím,
and Cyrillic -ому/-ему fragments. A short byte buffer reconstructs the
current word across token splits and resets at document boundaries.
"""
import re

READS = ()
VOWELS = frozenset('aeiouyаеёиоуыэюя')
# Russian possessives in the prepositional singular.
POSSESSIVES = {'моем', 'моём', 'твоем', 'твоём',
               'своем', 'своём', 'нашем', 'вашем'}
WORD_END = re.compile(r'[^\W\d_]+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else b''
    newest = prefix.token_bytes[-1]
    recent = (old + newest)[-200:]
    carry = (doc, recent)
    token = prefix.token_strings[-1]
    if token.endswith(('ому', 'ему')) and len(token.strip()) <= 4:
        return carry, 1.0
    if not token.endswith(('m', 'M', 'м', 'М')):
        return carry, 0.0

    stripped = token.strip()
    n = len(stripped)
    match = WORD_END.search(recent.decode('utf-8', errors='ignore'))
    word = match[0][-50:] if match else ''
    previous = old.decode('utf-8', errors='ignore')[-1:]
    continuing = token[:1].isalpha()
    prev_upper = continuing and previous.isupper()
    prev_lower = continuing and previous.islower()

    if token.endswith('м'):
        if word.lower().endswith(('шем', 'щем', 'чем')):
            # Standalone 'чем' is weaker than longer inflected words.
            value = 1.85 if len(word) <= 3 else 5.70
        elif word.lower() in POSSESSIVES:
            value = 4.0
        elif token.endswith('ом'):
            if prev_lower:
                if word.endswith('ном'):
                    value = 3.63
                elif word.endswith('ком'):
                    value = 3.36
                else:
                    value = 1.93
            else:
                value = 1.45 if n <= 4 else 0.63
        elif token.endswith(('ем', 'ём')):
            value = 1.74 if n <= 2 else 0.51
        else:
            value = 0.30 if token.endswith('ым') else 0.02
        return carry, value

    # Acute-accented vowel + m is a common Czech inflectional fragment.
    if stripped in ('ém', 'ím'):
        return carry, 1.2

    has_vowel = any(c in VOWELS for c in word.lower())
    if prev_upper:
        if not has_vowel:
            value = -4.14 if word.isupper() else -0.50
        elif n == 1:
            value = -1.47
        else:
            before = stripped.lower()[-2:-1]
            consonant = (bool(before) and before.isalpha()
                         and before not in VOWELS)
            value = -0.52 if consonant else -0.16
    elif not has_vowel:
        if len(word) <= 2:
            value = -0.07 if len(word) <= 1 else -0.19
        else:
            value = -0.43 if token.lower().endswith(('mm', 'мм')) else -1.08
    elif n == 1:
        value = -2.33 if len(word) <= 3 else -0.48
    else:
        value = 0.10 if prev_lower else 0.0
        if prev_lower and n <= 3 and token.endswith('m'):
            if token.endswith('em'):
                value = 0.55
            elif token.endswith(('om', 'ym')):
                value = 0.35
    return carry, value

programs.haiku:
"""Layer 1 MLP down-projection, feature 1876: a Slavic-"m" versus Latin-"M" detector.

What it responds to, on the current token (and whether it opens a document):

* Positive: a Cyrillic case ending spelled -ом / -ем / -ому, the masculine and neuter
  prepositional, instrumental and dative endings of adjectives, pronouns and nouns
  ("в текущем", "в ваш-ем", "на нижнем", "альб-ом"). The strongest are -ном, -ском,
  -нем, -ком (about 4), then short -ом / -ем pieces (about 1.8); a long word that only
  ends in -ом is weaker (about 0.6). Czech/Polish -ém / -ím are a weaker positive
  (about 0.9), and short Latin pieces ending in vowel+m (-em, -om, -am) a faint one (about 0.3).
* Negative: the Latin letter M closing an all-caps acronym or unit after a consonant
  ("PM", "CM", "FM", "DM", "NT|M"). Two-letter ones are about -2.5, longer ones
  about -1.5. A bare "M" after a capital consonant is the strongest case (about -2.9).
  Short lowercase pieces ending in consonant+m ("pm", "dm", "sm") are mildly negative
  (about -0.3), and a bare "m" is a little negative (about -0.25).
* Small negatives: the first token of a document or row (about -0.15), and the
  dotted-leader token "··" (about -1.5).

Everything else is 0. The values are rounded least-squares fits to a training sample.
"""

READS = ()

VOWELS = "AEIOUaeiou"


def _cyrillic(text):
    return bool(text) and all("Ѐ" <= c <= "ӿ" for c in text)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    v = 0.0
    if _cyrillic(tok):
        if tok.endswith(("ном", "ском", "нем", "ком")) and len(tok) <= 4:
            v = 3.9
        elif tok.endswith(("ом", "ем", "ём")):
            v = 1.8 if len(tok) <= 3 else 0.6
        elif tok.endswith("ому"):
            v = 1.4
    elif tok.isascii() and tok.isalpha() and tok[-1] == "M" and len(tok) >= 2:
        if tok.isupper() and tok[-2] not in VOWELS:
            v = -2.5 if len(tok) == 2 else -1.5
    elif tok == "M":
        v = -2.9 if prev[-1:].isupper() and prev[-1:] not in VOWELS else -0.1
    elif tok == "m":
        v = -0.25
    elif tok.isascii() and tok.isalpha() and tok.islower() and len(tok) <= 3:
        if tok[-1] == "m":
            v = -0.3 if tok[-2] not in VOWELS else 0.3
    elif tok[-2:] in ("ém", "ím", "ým"):
        v = 0.9
    if tok == "··":
        v = -1.5
    if new_doc:
        v -= 0.15
    return carry, float(v)

"""Component layers.1.mlp.down_proj:1877: an f-repetition detector.

Plain-language summary. Almost always this component is near zero. It turns negative
when the letter f comes right after another piece of text containing f:

  1. A piece with f that continues the word just before it, right after a piece with f:
     "fo" then "f" in code, "FUL" then "F", "ffiffiff": strongly negative.
  2. A word starting with f right after a word starting with f ("Film Festival",
     "Feel free", "Final Forecast"): negative.
  3. An f inside a word that already had an f earlier in the same word: negative.
  4. An f word one word after another f word ("family and friends"): slightly negative.
  5. Any other piece with f right after a piece with f: barely negative.

At a document's first token, which has no earlier context, it is slightly positive.
Otherwise it stays at 0.

The sizes are the mean activations of each case on training rows.
"""

READS = ()

DOC_START = 0.16      # first token of a document
DOC_START_F = -0.72   # first token of a document that starts with f (mostly content words)
TITLE_ALLIT = -1.9    # two capitalized f-words in a row ("Film Festival", "Final Fantasy")
REPEAT_PIECE = -3.0   # continuation piece starting with f right after an f-initial piece
SHORT_PIECE_AFTER_F = -2.0  # a 1-4 letter fragment with f right after a piece with f
PIECE_AFTER_F = -0.4  # a longer continuation piece with f right after a piece with f
WORD_ALLIT = -0.32    # word starting with f right after a word starting with f
IN_WORD = -0.10       # f inside a word that already contained an f
GAP1_F_WORD = -0.12   # f-initial word two pieces after an f-initial word
AFTER_F = -0.02       # any other piece with f right after a piece with f


def _starts_word(s):
    return s == "" or s[:1] in " \n\t"


def _is_title(s):
    return s.strip()[:1].isupper()


def _f_initial(s):
    return s.strip().lower().startswith("f")


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    t = s.lower()
    doc_start = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or doc_start:
        prev, prev2, word_has_f = None, None, False
    else:
        prev, prev2, word_has_f = carry
    new_word = _starts_word(s)
    if new_word:
        word_has_f = False  # a new word: earlier words don't count
    has_f = "f" in t
    if doc_start:
        value = DOC_START_F if _f_initial(s) else DOC_START
    elif not has_f or prev is None:
        value = 0.0
    elif not new_word and "f" in prev.lower():
        if _f_initial(s) and _f_initial(prev):
            value = REPEAT_PIECE
        elif len(s.strip()) <= 4:
            value = SHORT_PIECE_AFTER_F
        else:
            value = PIECE_AFTER_F
    elif new_word and _f_initial(s) and _f_initial(prev):
        value = TITLE_ALLIT if _is_title(s) and _is_title(prev) else WORD_ALLIT
    elif word_has_f:
        value = IN_WORD
    elif new_word and _f_initial(s) and prev2 is not None and _f_initial(prev2):
        value = GAP1_F_WORD
    elif "f" in prev.lower():
        value = AFTER_F
    else:
        value = 0.0
    return (s, prev, word_has_f or has_f), value

programs.sol:
"""Approximate large, lexically selective pulses at context beginnings.

The main contrasts are source-code opening syntax: Rust-style declarations
and documentation, test words, and literals are positive; primitive type
names and whitespace-prefixed operators are negative. Common grammatical
words, indentation and role labels get smaller corrections. Most later
tokens get zero.
An unchanged repeated opening token keeps its opening response; a few common
two-token headers have their own pulse. This is a surface-syntax heuristic,
not a general semantic or programming-language classifier. The small, dense
background activations later in a row are not modeled.
"""

READS = ()


def opening(s):
    # Formatting tokens are not opening brackets or source-code operators.
    if s.startswith('<|') and s.endswith('|>'):
        return 0.0
    if s == '[' or s.startswith('<?'):
        return 0.0
    w = s.lstrip(' \t(<')
    indented = s.startswith('\t')
    spaced = s.startswith(' ')
    bare = s == w

    if bare and w in {'user', 'assistant'}:
        return 3.45 if w == 'user' else 0.72

    # Distinctive source-file opening vocabulary.
    if bare and w in {'use', 'fn', 'pub'}:
        return 16.5
    if s in {'#[', '#!['} or s.startswith(('///', '//!')):
        return 10.5 if '\n' in s else 15.0
    if w in {'test', 'tests'}:
        return 11.5 if bare else 1.5
    if w in {'nil', 'Nil'}:
        return (16.5 if bare else 12.3) if w == 'nil' else 7.3
    if w in {'true', 'false', 'True', 'False', 'null', 'None'}:
        return 5.0 if bare else 3.8
    if w in {'int', 'uint', 'float', 'double'}:
        return -8.8 - (7.0 if indented else 4.5 if s[0] in '(<' else 0)
    if w in {'char', 'byte', 'string', 'String', 'Object'}:
        return -4.3 - (7.0 if indented else 6.0 if s[0] in '(<' else 0)
    if w in {'long', 'short'}:
        return -2.5
    if bare and w in {'function', 'func', 'def', 'export'}:
        return 5.2
    if bare and w in {'static', 'internal'}:
        return 5.3
    if bare and w in {'class', 'namespace', 'const', 'theorem'}:
        return 1.8
    if w == 'using':
        return -5.5 if bare else -2.1
    if bare and w == 'from':
        return -2.1
    if w in {'import', 'package'}:
        return -0.65
    if w in {'var', 'let'}:
        return -3.8
    if w == 'return':
        return 2.4 if bare else -12.3 if indented else -8.8
    if w == 'if':
        return -9.1 if indented else -3.1 if spaced else -0.25
    if w == 'while':
        return -6.8 if indented else -3.0
    if indented and w in {'for', 'assert', 'echo', 'print'}:
        return -7.0
    if spaced and w == 'new':
        return -3.55
    if bare and w == 'try':
        return 9.5
    if s in {'#ifndef', '#define'}:
        return -5.5

    # Operators and delimiters, preserving their leading whitespace.
    p = s.strip(' ')
    if spaced:
        if p in {'<', '<=', '==', '!='}:
            return -10.2
        if p in {'+', '<<'}:
            return -8.7
        if p in {'-', '$', '%'}:
            return -4.6
        if p in {'|', '&', '&&', '{'}:
            return -3.8
        if p in {'=', '=>'}:
            return -2.7
    if s == '()':
        return 7.0
    if s.startswith('/**'):
        return 2.3 if '\n' in s else 5.3
    if s.startswith('/*'):
        return 0.9 if '\n' in s else 2.1
    if s == '//':
        return 3.1
    if s in {'--', '%'}:
        return 3.1
    if p and set(p) <= set(')]}'):
        return 3.1 if ')' in p else 2.4
    if p in {'"""', "'''"}:
        return 3.3
    if s.startswith('\\"') or s in {'")', '\\")'}:
        return 2.6
    if s in {'\'', '`', '``', '"'}:
        return 1.6
    if s in {'(', ' ('}:
        return -1.0
    if s.startswith(('(', ' (', '[', ' [', '<', ' <')):
        return -1.4
    if s.isspace():
        if '\n' in s or '\r' in s:
            return 0.1
        if '\t' in s:
            return -2.2
        n = len(s)
        return -min(3.8, 0.3*n) if n % 4 == 3 else -min(1.7, 0.2*n)

    # Small natural-language opening effects.
    if bare and w in {'a', 'the'}:
        return 3.2
    if bare and w in {'in', 'on', 'at', 'of', 'to', 'and', 'with', 'it'}:
        return 2.0
    if s == ' The':
        return 1.6
    if s == 'An':
        return -2.4
    if spaced and w in {'the', 'a', 'A', 'of', 'to', 'and', 'by'}:
        return 0.5
    if spaced and w in {'is', 'are', 'was', 'were', 'be', 'been', 'being'}:
        return -0.7
    return -0.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or doc != carry[0]:
        carry = (doc, 0, token, s, True)
    _, n, first_id, first_text, repeated = carry
    repeated = repeated and token == first_id
    value = opening(s) if repeated else 0.0
    if n == 1:
        if first_text == 'Title' and s == ':':
            value = -4.97
        elif first_text == '//\n' and s == '//':
            value = -5.34
        elif first_text == '1' and s == '2':
            value = 2.42
    return (doc, n+1, first_id, first_text, repeated), value

programs.haiku:
"""Document-start feature of MLP neuron 1878 in layer 1 (down_proj).

What it does: this component is essentially silent except on the FIRST token of a
document (or of a packed row, where the model also restarts its positions). There, it
writes a value that depends on what kind of token opens the text:

  * code-ish opening tokens (type names and keywords such as `int`, `String`, `using`,
    `#define`) push it strongly negative;
  * operator-like or whitespace/indent opening tokens (` +`, ` =`, ` !=`, `\\t`, runs of
    spaces) push it moderately negative;
  * a few statement / block openers (`try`, `function`, `def`, `module`, `export`, `end`)
    push it strongly positive;
  * other capitalised opening words are mildly negative, lowercase words mildly positive,
    and everything else is near zero; every later token gets 0.

The true value is a fixed, token-specific number (the same token always gives the same
value at a document start), but the token classes above are a coarse approximation to it.
"""

READS = ()

CODE_WORDS = {
    "int", "double", "char", "float", "long", "byte", "bool", "String", "string", "Object",
    "void", "var", "using", "new", "print", "return", "const", "static", "file",
    "#define", "#ifndef", "#include",
}
BLOCK_WORDS = {"try", "function", "def", "module", "export", "end", "continue"}

CODE_VALUE = -3.9      # mean at document start for CODE_WORDS
OPERATOR_VALUE = -1.5  # mean for space + punctuation-only tokens, and whitespace runs
BLOCK_VALUE = 3.8      # mean for BLOCK_WORDS
UPPER_VALUE = -0.6     # mean for other capitalised opening words
LOWER_VALUE = 0.2      # mean for lowercase opening words
OTHER_VALUE = -0.1     # mean for everything else (punctuation, symbols, other scripts)


def _is_operator(text):
    body = text.strip()
    return text[:1] == " " and body != "" and not any(c.isalnum() for c in body)


def _is_whitespace(text):
    return text != "" and text.strip() == ""


def step(carry, prefix, upstream):
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return None, 0.0
    text = prefix.token_strings[-1]
    word = text.strip()
    if word in CODE_WORDS:
        value = CODE_VALUE
    elif word in BLOCK_WORDS:
        value = BLOCK_VALUE
    elif _is_operator(text) or _is_whitespace(text):
        value = OPERATOR_VALUE
    elif text[:1].isupper():
        value = UPPER_VALUE
    elif text[:1].islower():
        value = LOWER_VALUE
    else:
        value = OTHER_VALUE
    return None, float(value)

programs.sol:
"""Approximate a short, unspaced word-fragment response.

Single letters following letters are strongest. Two-letter fragments are
weaker, with vowel count and script separating different kinds of fragments.
Long words, leading spaces, digits, and sentence separators are mostly quiet.
Bare quotes, brackets, operators and escapes have their own positive response.
The first token of each document instead receives a negative baseline. This
is a shape/context approximation, not a dictionary of token-specific values.
"""
import unicodedata
from functools import lru_cache
import regex

READS = ()
SCRIPTS = ('Latin', 'Cyrillic', 'Arabic', 'Greek', 'Han',
           'Hiragana', 'Katakana', 'Hangul')
PATTERNS = [regex.compile(r'^\p{Script=' + name + r'}+$')
            for name in SCRIPTS]


@lru_cache(maxsize=32768)
def script(s):
    for name, pattern in zip(SCRIPTS, PATTERNS):
        if pattern.fullmatch(s):
            return name
    return 'other'


def fragment(s, previous):
    n = len(s)
    kind = script(s)
    inside = previous.isalpha()
    if n >= 4:
        return 0.12
    if kind == 'Han':
        return 0.53 if n == 1 else 0.24
    if kind in ('Hiragana', 'Katakana'):
        if n == 1:
            if 'SMALL' in unicodedata.name(s, '') or s == 'ん':
                return 1.9
            return 1.15 if kind == 'Katakana' else 0.55
        return 0.47 if n == 2 else 0.30
    if n == 3:
        return 0.30
    if kind == 'Latin' and s.isascii():
        vowels = sum(c.lower() in 'aeiou' for c in s)
        if n == 1:
            if inside:
                return 1.65 if s.islower() else 1.19
            if previous.isdigit():
                return 0.88 if s.islower() else 0.97
            return 0.53 if s.islower() else 0.13
        if inside:
            if not s.islower():
                return 0.43
            return 1.04 if vowels == 1 else 0.58
        if not s.islower():
            return 0.13
        return 0.60 if vowels else 0.21
    if n == 2:
        return 0.77 if kind == 'Latin' else 0.47
    if not inside:
        return 0.53
    return {'Cyrillic': 1.42, 'Arabic': 1.34,
            'Greek': 0.56, 'Latin': 0.90}.get(kind, 0.53)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    carry = (doc, s[-1:])
    if first:
        return carry, -1.6
    if s.isalpha():
        value = fragment(s, previous)
    elif s.isspace():
        value = -0.04
    elif s.strip() == '`':
        value = 0.85
    elif s[:1].isspace():
        value = 0.04 if s.isascii() else 0.21
    elif s and all(c in "'\"‘’“”" for c in s):
        value = 1.39 if len(s.encode('utf-8')) == 1 else 0.96
    elif s and all(c in '()[]{}' for c in s):
        value = 1.02 if len(s) == 1 else 0.24
    elif s and all(c in '=+>|*%&^' for c in s):
        value = 0.88
    elif s and all(c in '.,' for c in s):
        value = -0.06 if len(s) == 1 else -0.28
    elif s.startswith('\\'):
        if s[1:] in ('n', 'r', 't', '\n'):
            value = 0.0
        else:
            value = 0.85
    elif s.startswith('.') and s[1:].isalpha():
        value = 0.52 if len(s) == 3 else 0.26
    elif s and all(unicodedata.category(c).startswith('S') for c in s):
        value = 0.58
    elif '�' in s:
        value = 0.40
    elif s and all(unicodedata.category(c).startswith('P') for c in s):
        if not s.isascii():
            value = 0.02 if len(s) == 1 else -0.70
        else:
            value = 0.11 if s in ('/', '_', '-', '#', '~') else 0.34
            if len(s) > 1:
                value = 0.01
    else:
        value = 0.04 if s.isascii() else 0.21
    return carry, value

"""Negative on may/might, and on short spellings of the syllable 'ma'.

Subject pronouns modulate the modal response. The spelling response is
stronger across a token boundary after m or ma. English word frequency
attenuates familiar spellings. The spelling rules share Latin,
Greek, Cyrillic and Arabic letters through transliteration. This is an
approximation, not a grammatical parser.
"""
from functools import lru_cache
import unicodedata
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
ALPHABETIC = regex.compile(
    r"(?:[\p{Latin}\p{Greek}\p{Cyrillic}\p{Arabic}\p{M}\p{N}_]|[^\w])*\Z"
)


@lru_cache(maxsize=32768)
def spelling(text):
    # Do not mistake syllabic writing systems for strings of letters.
    return anyascii(text).lower() if ALPHABETIC.fullmatch(text) else ''


@lru_cache(maxsize=32768)
def rarity(word):
    return max(0.0, min(2.0, 5.2 - zipf_frequency(word, 'en')))


def modal(word, previous, spaced):
    if word == 'May':
        return -1.5 if spaced else -2.5
    if not spaced:
        return -4.3
    subject = previous.strip()
    lower = subject.lower()
    strengths = (2.45, 2.2)  # may, might
    if subject == 'I':
        strengths = (5.2, 3.8)
    elif lower in ('he', 'she'):
        strengths = (3.8, 3.8)
    elif lower in ('you', 'we'):
        strengths = (3.2, 2.2)
    elif lower in ('it', 'they'):
        strengths = (2.9, 2.65)
    elif lower in ('this', 'that', 'there'):
        strengths = (3.2, 2.9)
    elif lower in ('what', 'whatever', 'who'):
        strengths = (4.0, 3.5)
    index = int(word == 'might')
    strength = strengths[index]
    if subject[:1].isupper() and subject != 'I':
        strength += (0.6, 0.4)[index]
    return -strength


def fragment(word, split=False):
    if split and word == 'may':
        return -6.8
    if not (word.startswith('ma') and len(word) <= 4 and word.isalpha()):
        return 0.0
    r = rarity(word)
    if len(word) == 2:
        return -0.66 if split else -0.26
    consonant = word[2]
    if consonant in 'bdgjrvz':  # roughly voiced consonants
        strength = 1.8 + 0.18*r if split else 0.28 + 0.4*r
    elif consonant in 'cfhkpqstx':  # roughly voiceless consonants
        strength = 0.09 + 0.75*r if split else 0.03 + 0.49*r
    elif consonant in 'lmn':  # lateral and nasal sonorants
