"""layers.1.mlp.down_proj:1892 - a 'class' detector (negative on the word "class").

What it does: the component goes strongly negative on the token that completes the
word "class" as it is being typed, in any language: " class", "class", "classes",
"klasse", "clase", "classe", Russian "класс" (or its piece "асс" in "однокласс"),
Japanese "クラス", Korean "클래스". Everything else is predicted as 0.

How strong depends on how the word is used:
  - declaring a class in code ("public class", "export class", "base class", a line
    starting with "class"): about -3;
  - "class" in another script or language ("klasse", "classe", "класс"): about -5;
  - "class" as an ordinary English word in prose: about -1.4;
  - capitalised "Class": about -1;
  - a compound ending in class ("MyClass", "_class", "subclass"): about -1.2;
  - an HTML attribute (class="..."), after <span>, <div>, etc.: about -0.7.

It works on the word typed so far (the text since the last non-word character), so
"classical" or "classify" do not fire, and the stems only fire on the piece that
completes them. The levels are rounded means measured on training text.
"""

import re

READS = ()

# Word endings that spell "class" in various languages.
STEMS = ("class", "classes", "klass", "klasse", "clase", "clases", "classe", "klase",
         "клас", "класс", "класса", "классы", "クラス", "클래")
# Whole words that are the plain word "class" (not a compound).
PLAIN = ("class", "classes", "klass", "klasse", "clase", "clases", "classe", "klase")
CODE_BEFORE = {"public", "private", "protected", "export", "abstract", "static", "final",
               "base", "derived", "sealed", "partial", "new", "`"}
HTML_BEFORE = {"span", "div", "td", "li", "a", "p", "img"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    before = "" if carry is None or new_doc else carry        # the word typed before this token
    word = re.search(r"\w*$", (before + tok)[-40:]).group(0)  # the word typed so far
    lw = word.lower()
    if not any(lw.endswith(s) for s in STEMS) or any(before.lower().endswith(s) for s in STEMS):
        return word, 0.0                                       # not the token completing a stem
    if not word.isascii():
        return word, -5.0                                      # class in another script
    if lw not in PLAIN:
        return word, -1.2                                      # compound: MyClass, _class, subclass
    if word[0].isupper():
        return word, -1.0                                      # Class
    if lw != "class" and lw != "classes":
        return word, -5.0                                      # klasse, clase, classe, ...
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 and not new_doc else ""
    if prev.startswith("<") or prev in HTML_BEFORE:
        return word, -0.7                                      # class="..." attribute
    if prev in CODE_BEFORE or prev == "" or "\n" in prefix.token_strings[-2]:
        return word, -3.0                                      # declaration in code
