"""Definite modifiers and year-like digit sequences.

Predict a negative contribution on relational adjectives and place names just
following 'the', more strongly when capitalized. Some time modifiers behave
similarly. A fourth digit completing an 18xx/19xx/20xx prefix has another negative
response, especially when the number follows 'the'. Most tokens stay near zero.
These are grammatical averages: individual word differences and split-word
interactions are not reconstructed. A small middle-dot punctuation response is
also retained. State tracks digit runs and resets at document boundaries.
"""
from functools import lru_cache
import wordnet

READS = ()
TEMPORAL = frozenset(('early', 'late', 'recent', 'annual', 'historic',
                      'historical', 'ancient', 'modern', 'future', 'former',
                      'previous', 'current'))
BACKGROUND = 0.0001
# Century: second and third digits after 'the', then fourth digit without/with it.
YEAR_VALUES = {
    '18': (-0.6177, -0.3061, -0.4091, -2.4703),
    '19': (-0.9900, -0.2787, -0.8520, -3.7396),
    '20': (-0.4839, -0.1817, -0.2308, -2.7900),
}


@lru_cache(maxsize=32768)
def word_value(word, after_the, previous_capital):
    lower = word.lower()
    capital = word[0].isupper()
    cats = wordnet.categories(lower)
    adjective = 'adjective' in wordnet.parts_of_speech(lower)
    relational = 'adj.pert' in cats
    if after_the:
        if capital:
            if relational:
                return -1.1934
            if adjective:
                return -0.3354
            return -0.3906 if 'noun.location' in cats else -0.0845
        if lower in TEMPORAL:
            return -0.3901
        if relational:
            return -0.6007 if 'noun.person' in cats else -0.1731
        return -0.0357 if adjective else BACKGROUND
    if capital and previous_capital and adjective:
        return -0.0497
    return -0.0822 if capital and relational else BACKGROUND


def advance(carry, token, doc):
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', False)
    _, previous, before_previous, digits, definite = carry
    after_the = previous.strip().lower() == 'the'
    w = token.strip()
    value = BACKGROUND
    if token.isascii() and token.isdigit():
        if not digits:
            definite = after_the or (
                previous.isspace() and before_previous.strip().lower() == 'the')
        digits += token
        values = YEAR_VALUES.get(digits[:2])
        if values is not None:
            if len(digits) == 4:
                value = values[3] if definite else values[2]
            elif len(digits) == 3:
                value = values[1] if definite else 0.0657
            elif len(digits) == 2 and definite:
                value = values[0]
    else:
        digits = ''
        if after_the and token.isspace():
            value = -0.4830
        elif w.isascii() and w.isalpha():
            value = word_value(w, after_the, previous.strip()[:1].isupper())
        elif token == '··':
            value = 0.4036
    return (doc, token, previous, digits, definite), value


def step(carry, prefix, upstream):
    return advance(carry, prefix.token_strings[-1], prefix.document_ids[-1])

