RESPONSES = {
    'zero': (-5.1, -3.2, -5.1, -5.0),
    'silver': (-4.9, -0.8, -6.8, -2.3),
    'bell': (-4.7, -2.0, -7.5, -6.8),
}


def unfinished(data):
    """Keep only an incomplete UTF-8 character at the end."""
    for j in range(len(data) - 1, max(-1, len(data) - 5), -1):
        byte = data[j]
        if byte < 128:
            break
        if byte >= 192:
            width = 2 if byte < 224 else 3 if byte < 240 else 4
            return data[j:] if len(data) - j < width else b''
    return b''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, pending = b'', b''
    if carry is not None and carry[0] == doc:
        _, previous, pending = carry
    current = prefix.token_bytes[-1]
    joined = pending + current
    tail = unfinished(joined)
    text = joined.decode('utf-8', errors='ignore').strip()
    value = 0.0
    if current == b'\0':
        before = previous.decode('ascii', errors='ignore')
        if before and before[-1].isalpha():
            value = -1.6
        elif before and before[-1].isspace():
            value = -0.27
        elif before:
            value = -0.85
    elif len(current) == 1 and tail in PREFIXES:
        value = RESPONSES[PREFIXES[tail]][3]
    elif text and text[0] in FAMILIES:
        mode = 2 if pending else 0 if len(text) == 1 else 1
        value = RESPONSES[FAMILIES[text[0]]][mode]
    return (doc, current, tail), value

