programs.sol:
"""Approximate a negative response to short, closed Latin-letter spellings.

One a/e/i/o/u followed by consonants is the main cue. The rules emphasize
fragments completing a spelling begun earlier. English word frequency
moderates the response. Short -ed fragments and split -ing/-ed spellings
with a doubled consonant (as in pat + ting) are additional negative families.
The first token of a document instead gets a small positive baseline. Carry
keeps at most 30 trailing letters, and resets at document boundaries.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
VOWELS = 'aeiou'
STOP_CONSONANTS = 'bdgkpt'

@lru_cache(maxsize=65536)
def spelling(token):
    m = re.fullmatch(r'[^A-Za-z]*([A-Za-z]+)', token)
    if not m:
        return None
    s = m[1].lower()
    vowels = sum(c in VOWELS for c in s)
    onset = len(re.match('[^aeiou]*', s)[0])
    end = re.search('[aeiou]([^aeiou]*)$', s)
    tail = len(end[1]) if end else 0
    return s, vowels, onset, tail, zipf_frequency(s, 'en')

@lru_cache(maxsize=65536)
def english_frequency(word):
    return zipf_frequency(word.lower(), 'en')


def response(token, previous):
    info = spelling(token)
    if info is None:
        return 0.002
    s, vowels, onset, tail, frequency = info
    joined = bool(previous) and token.isascii() and token.isalpha()
    before = previous.lower() if joined else ''
    word = before + s
    previous_vowels = sum(c in VOWELS for c in before)

    # A spelling family: this is not a grammatical -ed suffix test.
    if vowels == 1 and s.endswith('ed'):
        if s[0] in STOP_CONSONANTS:
            return -1.64 if len(before) >= 4 else -0.53
        return -0.16

    # Split inflections of a short stem, with a doubled final consonant.
    if joined:
        inflection = re.fullmatch(
            r'(.+?)([bcdfghjklmnpqrstvwxyz])\2(ing|ed)', word)
        if inflection:
            stem = inflection[1] + inflection[2]
            if (len(stem) <= 6 and sum(c in VOWELS for c in stem) == 1
                    and english_frequency(word) <= 5.0):
                return -0.6 if inflection[3] == 'ing' else -0.35

    closed = previous_vowels + vowels == 1 and (tail > 0 or vowels == 0)
    if not closed:
        return 0.002
    final_stop = s[-1] in STOP_CONSONANTS
    if joined:
        if english_frequency(word) <= 1.75:
            return -0.12
        if s.endswith('s'):
            return -0.65
        return -0.53 if final_stop else -0.29
    if frequency > 5.1:
        return -0.01
    if not onset:
        return -0.012
    if len(s) > 4:
        return -0.016
    if final_stop:
        return -0.25 if tail == 1 else -0.136
    return -0.12


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry[0] != document
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = 0.25 if first else response(token, previous)
    if previous and token.isascii() and token.isalpha():
        word = (previous + token)[-30:]
    else:
        m = re.search('[A-Za-z]+$', token)
        word = m[0] if m else ''
    return (document, word[-30:]), value

