# Conventional multiword connectives, relative phrases, and comparisons.
PHRASES = {
    'even though': -1.5, 'just like': -1.5, 'much like': -1.1,
    'just as': -0.8, 'even as': -0.9, 'except as': -2.5,
    'virtue of': -1.0, 'together with': -0.4,
    'conjunction with': -0.4, 'combination with': -0.4,
    'which case': -4.8, 'which point': -3.7, 'which way': -1.0,
    'which time': -1.2, 'which of': 0.4,
    'what ever': -4.3, "who 's": -1.6, 'how come': -2.0,
    'what if': 0.8, 'what a': 0.3, 'what to': 0.4,
    'what the': 0.3, "what 's": 0.5, 'what that': 0.8,
    'like that': 1.1, 'after that': 0.7, 'similar to': 0.4,
    'something of': 1.3, 'by hand': -0.3,
}

# Split versus single-token versions of compound relative words.
RELATIVES = {
    'whereas': (-4.1, -0.3), 'wherever': (-4.6, -1.0),
    'whenever': (-2.0, -0.5), 'whoever': (-2.0, -1.2),
    'whatever': (-3.5, -0.1), 'whatsoever': (-4.5, -2.3),
    'whichever': (-1.2, -0.5),
}

