SPELLINGS = {
    'whiz': 5.5, 'wiz': 3.0, 'witz': 3.0, 'witt': 1.3,
    'whitt': 4.0, 'whir': 2.8, 'swir': 2.1, 'twir': 2.4,
    'whisk': 0.7, 'whal': 1.3, 'whack': 2.5, 'whistl': 1.9,
    'wurz': 2.0, 'wirk': 1.2, 'wund': 1.5, 'rhiz': 2.1,
    'huiz': 2.1, 'wurtz': 2.0, 'wijz': 2.0, 'whitel': 2.0,
}


def value(old, previous, token):
    s = token.lower()
    c, p = s.strip(), previous.lower().strip()
    text = old + s
    match = re.search(r'[a-z]+\Z', text)
    word = match.group() if match else ''
    split = bool(match and match.start() < len(old)
                 and not s[:1].isspace())

    compound = re.fullmatch(
        r'(here|there|where)(in|of|on|by|under|upon|to|from|after|'
        r'with|between|unto|at|through|fore|among)', word)
    if compound:
        root, end = compound.groups()
        if split:
            if not old.endswith(root):
                return 0.0
            if root == 'where':
                return -8.0 if end in ('in', 'of', 'upon') else -3.0
            if end == 'fore':
                return 0.0
            if end == 'by':
                return -3.5 if root == 'there' else -0.1
            if end in ('to', 'through', 'after'):
                return -0.5
            return -2.8 if root == 'here' else -2.5
        if root == 'where':
            return -2.7 if end == 'in' else -1.6
        if root == 'here':
            return -2.8 if end == 'by' else -0.4
        return -0.3 if end in ('by', 'of', 'in') else 0.0
    if word in RELATIVES:
        return RELATIVES[word][0 if split else 1]
    if (split and word in ('within', 'without', 'throughout')) or (
            p in ('with', 'through') and c == 'out'):
        return -3.8
    if split and word.endswith('ithout'):
        return -4.1
    if p == 'where' and c in ('in', 'on'):
        return -1.3
    # Oblique and neuter forms of Germanic relative pronouns.
    if split and re.fullmatch(r'h?vilk(et|en)', word):
        return -6.5 if word.endswith('et') else -3.0
    if split and re.fullmatch(r'welch(e|en|er|es)|welke?', word):
        if word.endswith('chen'):
            return -2.5
        return -1.4 if word.endswith(('cher', 'ke')) else -0.3

    if c in ('which', 'whom', 'whose'):
        if p in ('after', 'before', 'without'):
            return -3.3
        if c == 'whose':
            return -1.9 if p in ('with', 'in') else -0.3
        if c == 'whom':
            return -0.5
        return {'upon': -1.1, 'to': -0.35, 'of': -0.2,
                'through': -0.5}.get(p, 0.0)
    if c == 'turn' and p == 'in':
        return -1.6 if re.search(r'\bwh(?:ich|o),? in$', old) else -0.2
    phrase = p + ' ' + c
    if phrase in PHRASES:
        return PHRASES[phrase]
    if split and re.search(r'(which|whether|whilst|whither|whence)$', word):
        return -1.6
    if split and p in ('what', 'which', 'who', 'there'):
        return -3.0 if p == 'what' else -0.7

    for stem, strength in SPELLINGS.items():
        k = word.rfind(stem)
        if k < 0:
            continue
        ending = word[k + len(stem):]
        spin = stem in ('whir', 'swir', 'twir')
        suffix = r'(l|ls|led|ling|ler|ly|red|ring)?' if spin else r'(s|ing|ed|er|ly)?'
        new_stem = (k + len(stem) > len(word) - len(c)
                    and re.fullmatch(suffix, ending))
        inflection = (spin
                      and re.fullmatch(r'(l|ls|led|ling|ler|ly|red|ring)', c))
        if (new_stem or inflection) and (
                split or stem in ('whir', 'swir', 'twir', 'whisk')):
            if stem == 'whisk':
                sensory = re.search(r'mice|neur[oa]|stim|cortex|firing|sensory', old)
                return 0.2 if sensory else 1.3
            if stem == 'whal' and word.endswith('ing'):
                return 4.0
            if stem == 'witz' and c == 'itz':
                return 4.0
            return strength
    if not old:
        if c == '<|im_start|>':
            return 0.51
        if c.isascii() and c.isdigit():
            return -0.33
        if s.startswith(' ') and c in ('a', 'an'):
            return 0.48
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        old, previous = '', ''
    else:
        _, old, previous = carry
    token = prefix.token_strings[-1]
    prediction = value(old, previous, token)
    return (doc, (old + token.lower())[-80:], token), float(prediction)

