    "hereunder", "hereof", "whereby", "hereto", "thereto", "herewith",
}
CONNECTIVES = {
    "though", "whatever", "whenever", "wherever", "whichever", "whomever",
    "whom", "whose", "whither", "whereas", "although", "whereupon",
}
FOCUS_CONNECTIVES = {"which", "like", "in", "on", "case", "under", "as", "with", "from"}
FOCUS_WORDS = {
    "even", "just", "after", "there", "here", "with", "through",
    "where", "which", "when", "what", "as",
}
LEGAL_VALUE = -0.8
CONNECTIVE_VALUE = -0.4
FOCUS_CONN_VALUE = -0.3
FOCUS_BOOST = 3.0


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = _word(prefix.token_strings[-2]) if same_doc else ""
    if word in LEGAL_COMPOUNDS:
        value = LEGAL_VALUE
    elif word in CONNECTIVES:
