        character = (recent + raw).decode('utf8', 'replace')[-1:]
        if regex.match(r'\p{Script=Katakana}', character):
            value = 0.025
        elif regex.match(r'\p{Script=Hangul}', character):
            value = 0.26
        elif character == '\ufffd':
            value = 0.23
        else:
            value = 0.16
    elif text == '1' and line_start:
        value = 0.33 if previous.rstrip().endswith((':', '：')) else 0.19
    elif (word.isascii() and word.isalpha() and len(word) <= 3
          and word[-1].lower() in 'kgq'):
        value = 0.04

    # Coarse document-opening offset, then exceptional formatting transients.
    if position == 0:
        if word.isdigit():
            value = 0.035
        elif word.isascii() and word.isalpha() and word.istitle():
            value = -0.45 if len(word) > 1 else -0.27
        else:
            value = -0.22
        if text == 'Title':
            value = -1.22
        elif text == '1':
            value = -0.105
    elif position == 1:
        if previous == 'Title' and text == ':':
            value = 16.37
        elif previous == '1' and text == '2':
            value = 4.49

