        if raw == b'\r':
            value = 5.12
        elif text == '··':
            value = -1.53
    repeated = raw if position == 0 else repeated if repeated == raw else None
    if '\n' in text:
        line_start = not text.rsplit('\n', 1)[1].strip()
    elif text.strip():
        line_start = False
    carry = (doc, position + 1, text, line_start,
             (recent + raw)[-8:], repeated)
    return carry, value

