        if prev in ('is', 'are', 'was', 'were', 'be', 'been', 'being'):
            amount = 3.6
        elif prev in ('have', 'has', 'had'):
            amount = 3.0
        elif prev in ('in', 'of', 'for', 'through', 'during') or tail.endswith(','):
            amount = 6.0
        amount = MODIFIERS.get(prev, amount)
        negatives = ('not', 'no', "don't", "doesn't", "didn't", "won't")
        if any(w in negatives for w in words[-3:]) or 'n’t' in tail[-20:]:
            amount *= 0.5
        value = -amount
    elif word == 'of':
        if prev == 'much':
            value = 0.54 * last - 0.91
        else:
            value = {'most': -1.1, 'bit': -0.65, 'deal': -0.92}.get(prev, 0.0)
    elif word in ('lot', 'lots'):
        value = -0.75 if word == 'lots' else -0.15
        if prev in ('a', 'whole', 'awful'): value = -0.95
    elif word == 'little':
        value = -1.05 if prev == 'very' else -0.55
        if prev == 'the': value = -0.23
    elif word == 'bit':
        value = -0.9 if prev == 'little' else -0.05
        if prev in ('a', 'tiny'): value = -0.42
    elif word == 'deal' and prev in ('great', 'good'):
        value = -1.85 if prev == 'great' else -1.1
    elif word in ('thing', 'things'):
        if prev in ('this', 'these'):
            value = -1.9 if word == 'thing' else -2.5
        elif prev in ('that', 'those', 'such'): value = -1.5
        elif prev in ('many', 'all', 'new'): value = -0.55
    elif word in ('more', 'less') and prev in ('much', 'little', 'bit', 'lot', 'far'):
        value = -0.4
    else:
        value = spelling(stem, token)
    return (doc, (tail + token)[-100:], value), value

programs.haiku:
"""Mass-quantity 'much' detector (layers.1.mlp.down_proj, component 1919).

The component's activation is negative on the English word "much" when it is
used as a noun or pronoun: "This much is clear", "much of the town",
"spent much time" (about -4). "Much" opening a sentence is stronger (about -6).
"much" as a degree word after so, too, how, as, very or not is weaker (about
-1.7), and "pretty much" is about zero. The "of" right after "much" is also
negative (about -3.3). "a lot" gives about -0.9 on "lot", and "lots", "little",
"plenty", "bunch" give about -0.5. "of" after most, bit, deal or a quantity
gives about -0.4. Count quantifiers (many, few, several, some, all) leave it
near zero.

The program reads only the newest token and the one before it, so it keeps no
state between positions. It returns the predicted activation at each position.
The values are group means of the component's activation over training data.
"""

READS = ()

# Words that make "much" a degree word ("so much", "too much"): weaker there.
DEGREE_BEFORE_MUCH = {"so", "too", "how", "as", "very", "not"}
# Small mass quantities, weakly negative.
SMALL_MASS = {"lots", "little", "plenty", "bunch"}
# Words that, followed by "of", give a weak negative on "of".
QUANTITY_BEFORE_OF = {"most", "bit", "lot", "lots", "deal", "little", "plenty", "bunch"}


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    shown = prefix.token_strings[-1].strip()
    same_doc = len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""

    value = 0.0
    if word == "much":
        if prev == "pretty":
            value = 0.0
        elif prev in DEGREE_BEFORE_MUCH:
            value = -1.7
        elif shown[:1].isupper():
            value = -6.0  # "Much of ..." opening a sentence
        else:
            value = -4.0  # "much" as noun or pronoun
    elif word == "lot":
        value = -0.9 if prev in ("a", "whole", "awful") else 0.0  # "a lot", not "parking lot"
    elif word in SMALL_MASS:
        value = -0.5
    elif word == "of" and prev == "much":
        value = -3.3
    elif word == "of" and prev in QUANTITY_BEFORE_OF:
        value = -0.4
    return carry, float(value)
